import{_ as i,o,c as a,ag as e,j as n}from"./chunks/framework.DoUXNnsN.js";const x=JSON.parse('{"title":"Git","description":"","frontmatter":{"title":"Git","aliases":["git","版本控制","版本控制系统","VCS","Git入门"],"tags":["工具与工程","Git"],"status":"ai-draft","sources":["https://git-scm.com/book/zh/v2","https://git-scm.com/downloads","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":1},"headers":[],"relativePath":"50-工具与工程/Git/Git.md","filePath":"50-工具与工程/Git/Git.md"}'),s={name:"50-工具与工程/Git/Git.md"},l={style:{"overflow-x":"auto"}},d={viewBox:"0 0 760 210",style:{"min-width":"720px",width:"100%",height:"auto"},xmlns:"http://www.w3.org/2000/svg","font-family":"sans-serif","font-size":"14"};function c(r,t,p,h,g,u){return o(),a("div",null,[t[1]||(t[1]=e('<blockquote><p>本篇是 Git 系列的总览（hub）。读完你应该能：说清版本控制是什么、为什么不用&quot;最终版_v3_真的最终版.docx&quot;；画出 Git 的三个区；装好 Git 并完成首次配置；知道这个系列 5 篇该按什么顺序读。</p><p>本系列所有命令都在 Windows 11 + Git for Windows 2.54.0 的 Git Bash 里实际运行过，输出是真实复制的。Git 命令在 PowerShell 里写法相同；<code>echo</code>、<code>cat</code>、<code>sed</code> 这类<strong>非 Git</strong> 的命令在 PowerShell 里写法不同，文中会注明。每次运行产生的提交哈希（如 <code>d951209</code>）都不一样，你的结果和文中的哈希不同是正常的。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>Git 是一个<strong>分布式版本控制系统</strong>：它把你项目的每一次&quot;存档&quot;都完整记下来，让你随时回到任何一个历史时刻、同时开多条时间线做实验、再把成果合并回来，并且多人可以各自在自己的电脑上完整地协作。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a>：会打开终端、用 <code>cd</code> 进目录、用 <code>ls</code> 看文件。</li><li><a href="/Encyclopedia/50-工具与工程/PowerShell">PowerShell</a>（可选）：Windows 上另一种终端。</li><li>不需要任何编程基础，但需要知道&quot;文件&quot;&quot;文件夹&quot;是什么。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>先看没有版本控制时的典型一天：</p><ol><li>你写了 <code>报告.docx</code>，改了一版另存为 <code>报告_改.docx</code>，又改一版变成 <code>报告_改2_最终.docx</code>、<code>报告_最终版_真的.docx</code>。三天后你想找回&quot;周二下午删掉的那一段&quot;，只能一个个打开比对。</li><li>两个人改同一份文件，用邮件互发，最后谁也说不清谁改了哪里，合并靠肉眼。</li><li>程序出了 bug，你想知道&quot;这个 bug 是哪次改动引入的&quot;，没有记录可查。</li></ol><p>版本控制解决的正是这三件事：</p><table tabindex="0"><thead><tr><th>痛点</th><th>Git 的回答</th></tr></thead><tbody><tr><td>想回到过去</td><td>每次 commit 是一个完整快照，随时回退或对比</td></tr><tr><td>多人同时改</td><td>每人一份完整仓库，用分支和合并整合，冲突时明确告诉你哪几行冲突</td></tr><tr><td>想知道谁改了什么、为什么</td><td>每个 commit 记录作者、时间、说明；<code>git blame</code>、<code>git log</code> 可追溯</td></tr><tr><td>想大胆试验又怕搞坏</td><td>开一个分支随便改，不满意就丢掉，主线不受影响</td></tr></tbody></table><p>在公司里，MES、WMS 这类自研系统的 C# 代码、SQL 脚本、接口文档，都靠 Git 管理；发布、回滚、排查&quot;线上为什么变了&quot;都离不开它。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="快照而不是差异" tabindex="-1">快照而不是差异 <a class="header-anchor" href="#快照而不是差异" aria-label="Permalink to &quot;快照而不是差异&quot;">​</a></h3><p>Git 每次 commit 保存的是<strong>整个项目当时的样子（快照）</strong>，而不是&quot;这次改了什么&quot;。比喻：像相机每按一次快门拍一张全景照，而不是只记笔记&quot;左边椅子挪了 5cm&quot;。（实际存储时 Git 会去重压缩，未改动的文件只存一份引用，所以不会爆炸性占空间。）你看到的 <code>git diff</code>、<code>git log -p</code> 的&quot;改动&quot;，是 Git 现场比较两张快照算出来的。</p><h3 id="提交-commit-与哈希" tabindex="-1">提交（commit）与哈希 <a class="header-anchor" href="#提交-commit-与哈希" aria-label="Permalink to &quot;提交（commit）与哈希&quot;">​</a></h3><p>一次 commit = 一张快照 + 作者 + 时间 + 说明 + <strong>指向上一次 commit 的指针（父提交）</strong>。每个 commit 有一个由内容算出的 40 位十六进制编号，叫<strong>哈希</strong>（hash），平时只看前 7 位，如 <code>d951209</code>。多个 commit 通过&quot;父指针&quot;串成一条链：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C1 &lt;- C2 &lt;- C3        每个 commit 指向它的上一个</span></span></code></pre></div><h3 id="三个区" tabindex="-1">三个区 <a class="header-anchor" href="#三个区" aria-label="Permalink to &quot;三个区&quot;">​</a></h3><p>这是理解 Git 的第一把钥匙。你的文件在三个地方流动：</p>',19)),n("div",l,[(o(),a("svg",d,[...t[0]||(t[0]=[e('<rect x="20" y="40" width="190" height="90" rx="8" fill="currentColor" fill-opacity="0.08" stroke="currentColor"></rect><text x="115" y="75" text-anchor="middle" font-weight="bold">工作区</text><text x="115" y="100" text-anchor="middle">Working Directory</text><text x="115" y="118" text-anchor="middle" font-size="12">你在编辑器里看到的文件</text><rect x="285" y="40" width="190" height="90" rx="8" fill="currentColor" fill-opacity="0.15" stroke="currentColor"></rect><text x="380" y="75" text-anchor="middle" font-weight="bold">暂存区</text><text x="380" y="100" text-anchor="middle">Staging Area / Index</text><text x="380" y="118" text-anchor="middle" font-size="12">下一次 commit 要放什么</text><rect x="550" y="40" width="190" height="90" rx="8" fill="currentColor" fill-opacity="0.25" stroke="currentColor"></rect><text x="645" y="75" text-anchor="middle" font-weight="bold">本地仓库</text><text x="645" y="100" text-anchor="middle">Repository (.git)</text><text x="645" y="118" text-anchor="middle" font-size="12">所有历史快照</text><line x1="210" y1="70" x2="283" y2="70" stroke="currentColor" stroke-width="2"></line><polygon points="283,70 273,65 273,75" fill="currentColor"></polygon><text x="247" y="62" text-anchor="middle" font-size="12">git add</text><line x1="475" y1="70" x2="548" y2="70" stroke="currentColor" stroke-width="2"></line><polygon points="548,70 538,65 538,75" fill="currentColor"></polygon><text x="512" y="62" text-anchor="middle" font-size="12">git commit</text><line x1="283" y1="105" x2="212" y2="105" stroke="currentColor" stroke-width="2" stroke-dasharray="5 4"></line><polygon points="212,105 222,100 222,110" fill="currentColor"></polygon><text x="247" y="150" text-anchor="middle" font-size="12">git restore（丢弃改动）</text><line x1="548" y1="105" x2="477" y2="105" stroke="currentColor" stroke-width="2" stroke-dasharray="5 4"></line><polygon points="477,105 487,100 487,110" fill="currentColor"></polygon><text x="512" y="150" text-anchor="middle" font-size="12">git restore --staged</text><text x="380" y="195" text-anchor="middle" font-size="12">远程仓库（Gitee / GitHub）是第四个地方，见 Git远程仓库</text>',25)])]))]),t[2]||(t[2]=e(`<p>比喻：你要给全家拍合影。<strong>工作区</strong>是大家随意站着的客厅；<strong>暂存区</strong>是你让愿意入镜的人站到的&quot;取景框&quot;（谁没准备好就不进框）；<strong>commit</strong> 是按下快门，照片存入相册（仓库）。暂存区的意义是：你可以只挑这次想一起记录的改动提交，而不是工作区里所有改动一股脑提交。</p><h3 id="分支与-head" tabindex="-1">分支与 HEAD <a class="header-anchor" href="#分支与-head" aria-label="Permalink to &quot;分支与 HEAD&quot;">​</a></h3><p><strong>分支</strong>（branch）本质上只是一个&quot;贴在某个 commit 上的可移动标签&quot;，创建一个分支几乎零成本。<strong>HEAD</strong> 是&quot;你现在站在哪&quot;的指针，通常指向当前分支。详见 <a href="/Encyclopedia/50-工具与工程/Git/Git分支与合并">Git分支与合并</a>。</p><h3 id="本地仓库在哪" tabindex="-1">本地仓库在哪 <a class="header-anchor" href="#本地仓库在哪" aria-label="Permalink to &quot;本地仓库在哪&quot;">​</a></h3><p><code>git init</code> 会在项目文件夹里生成一个隐藏文件夹 <code>.git</code>，所有历史都在里面。删掉 <code>.git</code> 就等于删掉全部历史，项目文件夹本身变回普通文件夹——这也说明：<strong>Git 是本地的，不联网也能用</strong>；联网（Gitee/GitHub）只是多存一份并方便协作。</p><h2 id="安装与首次配置" tabindex="-1">安装与首次配置 <a class="header-anchor" href="#安装与首次配置" aria-label="Permalink to &quot;安装与首次配置&quot;">​</a></h2><ol><li>打开 <a href="https://git-scm.com/downloads" target="_blank" rel="noreferrer">https://git-scm.com/downloads</a> 下载 Windows 版（Git for Windows）安装，一路默认即可。安装后开始菜单里有 <strong>Git Bash</strong>（一个类 Linux 终端），PowerShell 里也能用 <code>git</code>。</li><li>验证：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git --version</span></span>
<span class="line"><span>git version 2.54.0.windows.1</span></span></code></pre></div><ol start="3"><li>告诉 Git 你是谁（每个 commit 都会署名，<strong>必须配</strong>，否则提交时会报错要求你配置）：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git config --global user.name &quot;你的名字&quot;</span></span>
<span class="line"><span>git config --global user.email &quot;you@example.com&quot;</span></span>
<span class="line"><span>git config --global init.defaultBranch main</span></span></code></pre></div><p><code>--global</code> 表示对你这个 Windows 用户的所有仓库生效，写入 <code>C:\\Users\\你的用户名\\.gitconfig</code>；<code>--local</code>（默认，不加 <code>--global</code> 时）只对当前仓库生效，写入仓库里的 <code>.git/config</code>。优先级：local 覆盖 global。公司项目和个人项目用不同邮箱时，进入仓库后单独 <code>git config user.email &quot;xx@company.com&quot;</code> 即可。</p><p>为了不改动你机器上的真实配置，我用环境变量 <code>GIT_CONFIG_GLOBAL</code> 把&quot;全局配置&quot;指到一个临时文件，演示上面三条命令的效果：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git config --global --list</span></span>
<span class="line"><span>user.name=Lab User</span></span>
<span class="line"><span>user.email=lab@example.com</span></span>
<span class="line"><span>init.defaultbranch=main</span></span>
<span class="line"><span>core.autocrlf=true</span></span></code></pre></div><p>对应的文件内容是普通的 INI 格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[user]</span></span>
<span class="line"><span>	name = Lab User</span></span>
<span class="line"><span>	email = lab@example.com</span></span>
<span class="line"><span>[init]</span></span>
<span class="line"><span>	defaultBranch = main</span></span>
<span class="line"><span>[core]</span></span>
<span class="line"><span>	autocrlf = true</span></span></code></pre></div><p>其中 <code>core.autocrlf=true</code> 是 Git for Windows 安装时的默认选项之一（把换行 CRLF/LF 自动转换），这就是你在 Windows 上 <code>git add</code> 时常看到下面这句警告的原因：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>warning: in the working copy of &#39;hello.txt&#39;, LF will be replaced by CRLF the next time Git touches it</span></span></code></pre></div><p>它只是提醒，不是错误，可以忽略（换行细节见 <a href="/Encyclopedia/10-计算机基础/数据表示/字符编码">字符编码</a>）。</p><h2 id="逐步例子" tabindex="-1">逐步例子 <a class="header-anchor" href="#逐步例子" aria-label="Permalink to &quot;逐步例子&quot;">​</a></h2><p>用 6 条命令走完&quot;创建仓库 → 提交 → 看历史&quot;的全过程（详细解释见 <a href="/Encyclopedia/50-工具与工程/Git/Git基础操作">Git基础操作</a>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git init -b main</span></span>
<span class="line"><span>Initialized empty Git repository in .../lab/.git/</span></span>
<span class="line"><span>$ echo &quot;hello git&quot; &gt; hello.txt</span></span>
<span class="line"><span>$ git add hello.txt</span></span>
<span class="line"><span>$ git commit -m &quot;add hello.txt&quot;</span></span>
<span class="line"><span>[main (root-commit) d951209] add hello.txt</span></span>
<span class="line"><span> 1 file changed, 1 insertion(+)</span></span>
<span class="line"><span> create mode 100644 hello.txt</span></span>
<span class="line"><span>$ git log --oneline</span></span>
<span class="line"><span>d951209 add hello.txt</span></span></code></pre></div><p>看到 <code>root-commit</code> 说明这是仓库的第一个提交（没有父提交）。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p>在任意空文件夹（比如桌面上新建的 <code>git-lab</code>）里打开 Git Bash，照着做：</p><ol><li><code>git init -b main</code>，应看到 <code>Initialized empty Git repository</code>。</li><li><code>git config user.name &quot;你的名字&quot;</code>、<code>git config user.email &quot;你的邮箱&quot;</code>（只对这个仓库生效）。</li><li>新建 <code>hello.txt</code>，写一行字。</li><li><code>git status</code>，应看到 <code>Untracked files: hello.txt</code>。</li><li><code>git add hello.txt</code>，再 <code>git status</code>，应变成 <code>Changes to be committed</code>。</li><li><code>git commit -m &quot;add hello.txt&quot;</code>，再 <code>git log --oneline</code>，应看到一行记录。</li></ol><p>在 PowerShell 里第 3 步用 <code>&quot;hello git&quot; | Out-File hello.txt -Encoding utf8</code>；注意本机 PowerShell 5.1 里直接用 <code>echo &quot;x&quot; &gt; file</code> 生成的文件带 UTF-8 BOM（实测前 3 个字节为 239 187 191），Git 能处理，但 <code>git diff</code> 会在第一行多出一个看不见的字符。想避免，就用编辑器或 Git Bash 创建文件。</p><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td><code>Author identity unknown / Please tell me who you are</code></td><td>没配 <code>user.name</code>/<code>user.email</code></td><td>按上文配置</td></tr><tr><td><code>fatal: not a git repository</code></td><td>当前目录不在仓库里</td><td><code>cd</code> 到仓库内，或先 <code>git init</code></td></tr><tr><td><code>dubious ownership in repository</code></td><td>仓库目录属于另一个 Windows 用户</td><td>确认可信后 <code>git config --global --add safe.directory &lt;路径&gt;</code>（别图省事全部放行）</td></tr><tr><td>分支叫 <code>master</code> 不叫 <code>main</code></td><td>老版本默认名</td><td><code>init.defaultBranch main</code>，或 <code>git init -b main</code></td></tr><tr><td>中文文件名显示成 <code>\\346\\226...</code></td><td><code>core.quotepath</code> 转义</td><td><code>git config --global core.quotepath false</code></td></tr><tr><td>到处是 CRLF 警告</td><td><code>core.autocrlf</code></td><td>可忽略；团队可统一用 <code>.gitattributes</code></td></tr></tbody></table><h2 id="本系列入门路径" tabindex="-1">本系列入门路径 <a class="header-anchor" href="#本系列入门路径" aria-label="Permalink to &quot;本系列入门路径&quot;">​</a></h2><p>按下面顺序读，每篇都带可运行的实验：</p><ol><li><strong><a href="/Encyclopedia/50-工具与工程/Git/Git基础操作">Git基础操作</a></strong>：<code>init / add / commit / status / log / diff</code>，以及 <code>.gitignore</code>。先把&quot;本地存档&quot;用熟。</li><li><strong><a href="/Encyclopedia/50-工具与工程/Git/Git分支与合并">Git分支与合并</a></strong>：<code>branch / switch / merge / rebase</code>。学会开分支并合并。</li><li><strong><a href="/Encyclopedia/50-工具与工程/Git/Git远程仓库">Git远程仓库</a></strong>：<code>clone / remote / push / pull</code>，Gitee 与 GitHub，SSH 与 HTTPS，凭据安全。</li><li><strong><a href="/Encyclopedia/50-工具与工程/Git/Git冲突与撤销">Git冲突与撤销</a></strong>：制造并解决合并冲突；<code>restore / reset / revert</code> 的区别；<code>reflog</code> 救命。</li><li><strong><a href="/Encyclopedia/50-工具与工程/Git/Git工作流">Git工作流</a></strong>：feature 分支、Pull Request、提交信息规范、团队约定。</li></ol><p>只想&quot;先能用&quot;：读完 1 和 3 就够日常；想&quot;不怕搞砸&quot;：补上 4。</p><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><p><strong>1.</strong> 暂存区存在的意义是什么？ 答：让你自己挑选这次要提交的改动。例如同时改了 A、B 两个文件，可以只 <code>git add A</code> 并提交，B 留到下一次。</p><p><strong>2.</strong> 你在仓库里 <code>git config user.email &quot;a@x.com&quot;</code>，全局配置里是 <code>b@y.com</code>，提交时用哪个？ 答：<code>a@x.com</code>，local 优先于 global。</p><p><strong>3.</strong> 把项目文件夹里的 <code>.git</code> 删掉会怎样？ 答：所有历史和分支都没了，只剩当前工作区的文件。所以不要手贱删，也不要随便把 <code>.git</code> 打包发给别人（里面有完整历史，可能含密码）。</p><p><strong>4.</strong> 为什么 Git 不联网也能提交、看历史、开分支？ 答：每个人的本地仓库都有完整历史，联网只用于和远程同步。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>版本控制 = 可回溯的存档 + 多人协作 + 可放心试验。</li><li>Git 记的是快照；commit 通过父指针串成链；分支只是指针。</li><li>三个区：工作区 -&gt; <code>git add</code> -&gt; 暂存区 -&gt; <code>git commit</code> -&gt; 本地仓库。</li><li>第一次使用必配 <code>user.name</code> 和 <code>user.email</code>。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/50-工具与工程/Git/Git基础操作">Git基础操作</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git分支与合并">Git分支与合并</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git远程仓库">Git远程仓库</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git冲突与撤销">Git冲突与撤销</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git工作流">Git工作流</a>、<a href="/Encyclopedia/50-工具与工程/工具与工程">工具与工程</a>、<a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a>、<a href="/Encyclopedia/50-工具与工程/CI-CD">CI-CD</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>Pro Git（中文版，免费在线）：<a href="https://git-scm.com/book/zh/v2" target="_blank" rel="noreferrer">https://git-scm.com/book/zh/v2</a>，Git 最权威的入门书。</li><li>Git for Windows 下载：<a href="https://git-scm.com/downloads" target="_blank" rel="noreferrer">https://git-scm.com/downloads</a></li></ul>`,43))])}const b=i(s,[["render",c]]);export{x as __pageData,b as default};
